CREATE OR REPLACE FUNCTION public.turn_settle_holds(p_actor_id uuid, t turns, p_charge integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
